def comps_of(g,bg=None):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    if bg is None: bg=g[0][0]
    seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
